-- Creates the api_keys table.
--
-- A key is stored as a public lookup identifier and the SHA-256 hash of its
-- secret part. The full key is never stored. Timestamps have no database
-- default: the application supplies them from its injected clock. Identifiers
-- are UUIDs generated by the application.

CREATE TABLE api_keys (
  id uuid NOT NULL,
  lookup_id varchar(16) NOT NULL,
  secret_hash varchar(64) NOT NULL,
  merchant_id uuid,
  role varchar(20) NOT NULL,
  created_at timestamptz NOT NULL,
  revoked_at timestamptz,
  CONSTRAINT api_keys_pkey PRIMARY KEY (id),
  CONSTRAINT api_keys_lookup_id_key UNIQUE (lookup_id),
  CONSTRAINT api_keys_merchant_id_fkey FOREIGN KEY (merchant_id) REFERENCES merchants (id),
  -- 8 random bytes in lowercase hexadecimal.
  CONSTRAINT api_keys_lookup_id_check CHECK (lookup_id ~ '^[0-9a-f]{16}$'),
  -- SHA-256 digest in lowercase hexadecimal.
  CONSTRAINT api_keys_secret_hash_check CHECK (secret_hash ~ '^[0-9a-f]{64}$'),
  -- A platform key has no merchant and the platform administrator role. A
  -- merchant key references a merchant and has a merchant role. Any other role,
  -- including PLATFORM_OPERATOR, or any other pairing is rejected.
  CONSTRAINT api_keys_role_scope_check CHECK (
    (merchant_id IS NULL AND role = 'PLATFORM_ADMIN')
    OR (merchant_id IS NOT NULL AND role IN ('MERCHANT_ADMIN', 'MERCHANT_READ_ONLY'))
  )
);

COMMENT ON TABLE api_keys IS 'API keys for server-to-server authentication. Only the lookup identifier and the SHA-256 hash of the secret are stored. Rows are never deleted, and the only change allowed is setting revoked_at once.';
COMMENT ON COLUMN api_keys.lookup_id IS 'Public identifier embedded in the key, used to find the row before the secret is compared.';
COMMENT ON COLUMN api_keys.secret_hash IS 'SHA-256 of the secret part of the key, as 64 lowercase hexadecimal characters. Safe because the secret has 256 bits of entropy.';
COMMENT ON COLUMN api_keys.merchant_id IS 'The merchant the key belongs to. NULL for a platform key.';
COMMENT ON COLUMN api_keys.revoked_at IS 'Set once by revocation. A key with a value here never authenticates again and cannot be reactivated.';

-- Only revoked_at can change, and only from NULL to a value. This makes a revoked
-- key impossible to reactivate or to repurpose by rewriting its hash or scope.
CREATE FUNCTION api_keys_reject_invalid_update() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF (NEW.id, NEW.lookup_id, NEW.secret_hash, NEW.merchant_id, NEW.role, NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.lookup_id, OLD.secret_hash, OLD.merchant_id, OLD.role, OLD.created_at) THEN
    RAISE EXCEPTION 'api_keys: only revoked_at can be changed'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.revoked_at IS NOT NULL AND NEW.revoked_at IS DISTINCT FROM OLD.revoked_at THEN
    RAISE EXCEPTION 'api_keys: a revoked key cannot be reactivated or revoked again'
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER api_keys_restrict_update
BEFORE UPDATE ON api_keys
FOR EACH ROW
EXECUTE FUNCTION api_keys_reject_invalid_update();

-- Deleting a revoked row and inserting it again would reactivate the key.
CREATE FUNCTION api_keys_reject_removal() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'api_keys rows are never removed: % is not allowed', TG_OP
    USING ERRCODE = 'restrict_violation';
END;
$$;

-- A statement-level trigger also rejects statements that match no row.
CREATE TRIGGER api_keys_no_removal
BEFORE DELETE OR TRUNCATE ON api_keys
FOR EACH STATEMENT
EXECUTE FUNCTION api_keys_reject_removal();
